const crypto = require("node:crypto");
(async () => {
  const email = process.argv[1];
  const event = { id: "evt_smoke_" + Date.now(), type: "checkout.session.completed",
    data: { object: { id: "cs_smoke_" + Date.now(), metadata: { email } } } };
  const raw = JSON.stringify(event);
